package com.bank.status;

// Routes by status content using equals, never ==, because runtime-built
// strings are not identity-equal to the pooled literal.
class StatusComparator {

    boolean isSettled(String status) {
        return "SETTLED".equals(status); // content comparison — always correct
    }

    // WRONG version kept only to demonstrate the bug.
    boolean isSettledByReference(String status) {
        return status == "SETTLED"; // identity comparison — fails for runtime strings
    }
}
