package com.bank.status;

import java.nio.charset.StandardCharsets;
import java.util.logging.*;

public class StringCreationDemo {
    private static final Logger log = Logger.getLogger(StringCreationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        StatusComparator comparator = new StatusComparator();

        // 1) LITERAL — pooled and shared.
        String literal1 = "SETTLED";
        String literal2 = "SETTLED";
        log.info(() -> "literal1 == literal2 ? " + (literal1 == literal2) + " (shared pool object)");

        // 2) new String — distinct heap object.
        String viaNew = new String("SETTLED");
        log.info(() -> "viaNew == literal1 ? " + (viaNew == literal1)
                + " (different object) ; equals ? " + viaNew.equals(literal1));

        // 3) from char[] — distinct heap object.
        String viaChars = new String(new char[]{'S','E','T','T','L','E','D'});
        log.info(() -> "viaChars == literal1 ? " + (viaChars == literal1)
                + " ; equals ? " + viaChars.equals(literal1));

        // 4) from byte[] + Charset — distinct heap object; ALWAYS specify charset.
        byte[] bytes = "SETTLED".getBytes(StandardCharsets.UTF_8);
        String viaBytes = new String(bytes, StandardCharsets.UTF_8);
        log.info(() -> "viaBytes == literal1 ? " + (viaBytes == literal1)
                + " ; equals ? " + viaBytes.equals(literal1));

        // intern() recovers the pooled canonical object.
        String interned = viaNew.intern();
        log.info(() -> "viaNew.intern() == literal1 ? " + (interned == literal1) + " (canonical)");

        // 5) The routing bug and the fix.
        log.warning(() -> "Routing by == on runtime string: "
                + comparator.isSettledByReference(viaBytes) + " (BUG — misroutes!)");
        log.info(() -> "Routing by equals on runtime string: "
                + comparator.isSettled(viaBytes) + " (CORRECT)");
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
